<form method="post" id="validationForm" class="d-none"><input type="hidden" name="action" value="validar"><input type="hidden" name="codpotencial" id="potentialId"><input type="hidden" name="status" id="potentialStatus"></form><script src="../assets/vendor/bootstrap/js/bootstrap.bundle.min.js?v=2"></script><script src="../assets/js/ia-potenciais-categoria.js?v=2"></script><script>document.addEventListener('DOMContentLoaded',function(){var fragment=document.querySelector('[data-ia-category]'),selected=null,rows=fragment?fragment.querySelectorAll('[data-row]'):[],buttons=fragment?fragment.querySelectorAll('[data-action]'):[];rows.forEach(function(row){row.addEventListener('click',function(e){if(e.target.closest('button,a,select,textarea'))return;var radio=row.querySelector('input[name=selected]');if(!radio)return;radio.checked=true;selected=radio.value;rows.forEach(function(x){x.classList.remove('selected')});row.classList.add('selected');buttons.forEach(function(x){x.disabled=false})})});buttons.forEach(function(btn){btn.addEventListener('click',function(){if(!selected)return;if(btn.dataset.action==='APROVADO'&&window.iaDestinoAbrir){window.iaDestinoAbrir(selected);return;}var ok=btn.dataset.action==='APROVADO';if(!confirm(ok?<?=json_encode($labels['confirmApprove'],JSON_UNESCAPED_UNICODE)?>:<?=json_encode($labels['confirmReject'],JSON_UNESCAPED_UNICODE)?>))return;document.getElementById('potentialId').value=selected;document.getElementById('potentialStatus').value=btn.dataset.action;document.getElementById('validationForm').submit()})})});</script><?php if ($iaDestinoAtivo) require __DIR__ . '/ia_potenciais_destino_modal.inc.php'; ?><?php require_once dirname(__DIR__) . '/components/toolbar_grupos.php'; greenPortalToolbarGruposAuto(); ?></body></html>
